package com.logatron.architecture;
import com.tngtech.archunit.core.domain.JavaClasses;import com.tngtech.archunit.core.importer.ClassFileImporter;import com.tngtech.archunit.lang.ArchRule;import org.junit.jupiter.api.*;import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.*;
class ArchitectureTest{private static JavaClasses classes;@BeforeAll static void load(){classes=new ClassFileImporter().importPackages("com.logatron");}@Test void controllersDoNotDependOnRepositories(){noClasses().that().haveSimpleNameEndingWith("Controller").should().dependOnClassesThat().haveSimpleNameEndingWith("Repository").check(classes);}@Test void commonDoesNotDependOnFeatures(){noClasses().that().resideInAPackage("com.logatron.common..").should().dependOnClassesThat().resideInAnyPackage("com.logatron.auth..","com.logatron.catalog..","com.logatron.administration..","com.logatron.audit..").check(classes);}@Test void catalogDoesNotDependOnAdministration(){noClasses().that().resideInAPackage("com.logatron.catalog..").should().dependOnClassesThat().resideInAPackage("com.logatron.administration..").check(classes);}}
